import { z } from 'zod';
import { DomainError, notImplemented, type UseCase, type UseCaseContext } from '@agentic-ddd/core';
import { AgentUseCase } from '@agentic-ddd/decorators';
import { Task } from '../domain/task';
import { TaskCreated } from '../domain/task.events';
import type { TaskRepository } from '../domain/task.repository';

export const createTaskInput = z.object({ task_id: z.string().min(1), title: z.string().min(1) });
export const createTaskOutput = z.object({ task_id: z.string(), title: z.string(), status: z.literal('pending') });
export type CreateTaskInput = z.infer<typeof createTaskInput>;
export type CreateTaskOutput = z.infer<typeof createTaskOutput>;

@AgentUseCase({ name: 'create_task', description: 'Cria, salva e publica uma tarefa pendente; id repetido falha com TASK_ALREADY_EXISTS.', whenToUse: 'Quando o usuário deseja criar uma tarefa.', whenNotToUse: 'Para concluir tarefa existente.', input: createTaskInput, output: createTaskOutput, uses: ['method:Task.create'], emits: [TaskCreated] })
export class CreateTask implements UseCase<CreateTaskInput, CreateTaskOutput> {
  constructor(private readonly tasks: TaskRepository) {}
  async execute(input: CreateTaskInput, ctx: UseCaseContext): Promise<CreateTaskOutput> {
    if ((await this.tasks.findById(input.task_id)) !== null) throw new DomainError('TASK_ALREADY_EXISTS', 'Tarefa já existe.');
    const task = Task.create(input.task_id, input.title);
    await this.tasks.save(task);
    await ctx.publish(task.pullEvents());
    return { task_id: task.id, title: task.title, status: 'pending' };









  }
}

import { describe, expect, test } from 'bun:test';
import { covers } from '@agentic-ddd/testing';
import type { DomainEvent, UseCaseContext } from '@agentic-ddd/core';
import { TaskCreated } from '../domain/task.events';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';
import { CreateTask } from '../application/create-task';

function setup() {
  const published: DomainEvent[] = [];
  const ctx: UseCaseContext = { correlationId: 'c', causationId: 'k', publish: async (e) => { published.push(...e); } };
  return { published, ctx, repo: new InMemoryTaskRepository() };
}

describe('CreateTask', () => {
  test(covers(['usecase:create_task'], 'cria tarefa pendente, salva e publica TaskCreated com título aparado'), async () => {
    const { published, ctx, repo } = setup();
    const uc = new CreateTask(repo);
    expect(await uc.execute({ task_id: 't1', title: '  Escrever  ' }, ctx)).toEqual({ task_id: 't1', title: 'Escrever', status: 'pending' });
    expect((await repo.findById('t1'))!.title).toBe('Escrever');
    expect(published).toHaveLength(1);
    expect(published[0]).toBeInstanceOf(TaskCreated);
  });

  test(covers(['usecase:create_task', 'criterion:0001/persistencia-criacao'], 'salva, publica TaskCreated, retorna pending e rejeita duplicado com TASK_ALREADY_EXISTS'), async () => {
    const { published, ctx, repo } = setup();
    const uc = new CreateTask(repo);
    expect(await uc.execute({ task_id: 't1', title: 'Escrever testes' }, ctx)).toEqual({ task_id: 't1', title: 'Escrever testes', status: 'pending' });
    expect((await repo.findById('t1'))!.status).toBe('pending');
    expect(published).toHaveLength(1);
    expect(published[0]).toBeInstanceOf(TaskCreated);
    expect(published[0]!.payload).toEqual({ taskId: 't1', title: 'Escrever testes' });
    await expect(uc.execute({ task_id: 't1', title: 'Outro' }, ctx)).rejects.toMatchObject({ code: 'TASK_ALREADY_EXISTS' });
    expect(published).toHaveLength(1);
  });
});
